// Automatización sin IA: reglas fijas
const CLIENTE_SESION = 'C-102';
const DUENO = { '4521': 'C-102', '4540': 'C-102', '5310': 'C-311' };
const ENVIOS = {
  '4521': { estado: 'Retenido en aduana', fecha_estimada: '2026-10-30' },
  '4540': { estado: 'Entregado', fecha_estimada: '2026-10-20' },
  '5310': { estado: 'En reparto', fecha_estimada: '2026-10-27' },
};
const texto = $input.first().json.chatInput ?? '';
const numero = (texto.match(/\b\d{4}\b/) ?? [])[0];
let output;
if (!numero) {
  output = 'Para rastrear tu pedido, escríbeme su número de cuatro dígitos.';
} else if (DUENO[numero] !== CLIENTE_SESION) {
  output = `No encuentro el pedido ${numero} en tu cuenta. ¿Puedes verificar el número?`;
} else {
  const e = ENVIOS[numero];
  output = `Tu pedido ${numero} está: ${e.estado}. Fecha estimada: ${e.fecha_estimada}.`;
}
return [{ json: { output } }];

