  '5310': { transportadora: 'EnvíaYa', estado: 'En reparto', fecha_estimada: '2026-10-27' },
};
const numero = String(query.numero_pedido ?? '').trim();
const pedido = PEDIDOS[numero];
// Control de identidad: solo pedidos del cliente de la sesión
if (!pedido || pedido.cliente !== CLIENTE_SESION) {
  return JSON.stringify({ error: 'Pedido no encontrado para este cliente.' });
}
const { cliente, ...datos } = pedido;
return JSON.stringify({ numero_pedido: numero, ...datos });

