  '4521': { cliente: 'C-102', fecha_compra: '2026-10-12', productos: ['Juego de ollas'], valor: 280000, estado: 'En tránsito' },
  '4540': { cliente: 'C-102', fecha_compra: '2026-10-08', productos: ['Microondas 20 L'], valor: 420000, estado: 'Entregado el 2026-10-20' },
  '5310': { cliente: 'C-311', fecha_compra: '2026-10-15', productos: ['Licuadora'], valor: 190000, estado: 'En tránsito' },
};
const ENVIOS = {
  '4521': { transportadora: 'EnvíaYa', estado: 'Retenido en aduana', fecha_estimada: '2026-10-30' },
  '4540': { transportadora: 'EnvíaYa', estado: 'Entregado', fecha_estimada: '2026-10-20' },
  '5310': { transportadora: 'EnvíaYa', estado: 'En reparto', fecha_estimada: '2026-10-27' },
};
const numero = String(query.numero_pedido ?? '').trim();
const pedido = PEDIDOS[numero];
// Control de identidad: solo pedidos del cliente de la sesión
if (!pedido || pedido.cliente !== CLIENTE_SESION) {
  return JSON.stringify({ error: 'Pedido no encontrado para este cliente.' });
}
const monto = Math.round(Number(query.monto) || 0);
// Control: el monto no puede superar el valor del pedido
if (monto > pedido.valor) {
  return JSON.stringify({ error: 'El monto supera el valor del pedido.' });
}
// Nada se ejecuta. En producción, esta propuesta se guarda en una tabla y una persona la aprueba.
return JSON.stringify({
  id_propuesta: 'P-' + String(Date.now()).slice(-4),
  estado: 'pendiente_de_aprobacion',
  resumen: `Pedido ${numero} (${pedido.productos.join(', ')}, valor ${pedido.valor} COP). Propuesta: ${query.tipo} por ${monto} COP. Motivo: ${query.motivo}`,
});

